/**
 * Writes `src/app/core/config/site-url.ts` from the resolved deployment origin.
 *
 * Committed rather than ignored: `ng serve` and `ng test` do not run the build
 * scripts, and a missing generated file would break them. The checked-in value
 * is the production default, so a regenerated file only ever differs on a
 * preview or a custom-origin build.
 *
 *   node tools/generate-site-url.mjs
 */
import { writeFileSync } from 'node:fs';

import { resolveOrigin } from './site-origin.mjs';

const origin = resolveOrigin();

writeFileSync(
  new URL('../src/app/core/config/site-url.ts', import.meta.url),
  `/**
 * GENERATED by tools/generate-site-url.mjs — do not edit by hand.
 *
 * Regenerated on every build from the deployment environment. See
 * tools/site-origin.mjs for how the value is chosen.
 */
export const SITE_URL = '${origin}';
`,
);

console.info(`site-url.ts written with origin ${origin}`);
